<#
.SYNOPSIS
    hy — Codex 版工作流插件 一键安装器（自包含，全局安装）
.DESCRIPTION
    解压内置插件并部署到 ~/.codex/（skills/ agents/ hooks/scripts/ + AGENTS.md + hooks.json + config.toml）
.EXAMPLE
    .\install.ps1
#>
param()

$ErrorActionPreference = "Stop"
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
Write-Host "[i] hy 插件安装器（Codex 版）v1.0" -ForegroundColor Cyan
Write-Host ""

$CodexDir = Join-Path $HOME ".codex"
New-Item -ItemType Directory -Path $CodexDir -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "skills") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "agents") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path (Join-Path $CodexDir "hooks") "scripts") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "mcp") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "reference") -Force | Out-Null
Write-Host "[i] 解压插件到临时目录 ..." -ForegroundColor Cyan

$b64 = ''
$bytes = [Convert]::FromBase64String($b64)
$tempTar = Join-Path ([System.IO.Path]::GetTempPath()) "hy_codex_$([System.IO.Path]::GetRandomFileName()).tar.gz"
[System.IO.File]::WriteAllBytes($tempTar, $bytes)

$TmpDir = Join-Path ([System.IO.Path]::GetTempPath()) "hy-codex-$([System.IO.Path]::GetRandomFileName())"
New-Item -ItemType Directory -Path $TmpDir -Force | Out-Null
# 优先使用 Windows 自带 tar.exe（Git Bash 的 GNU tar 不认 Windows 路径）
$TarExe = if (Test-Path (Join-Path $env:SystemRoot "System32\tar.exe")) {
    Join-Path $env:SystemRoot "System32\tar.exe"
} else { "tar" }
& $TarExe -xzf $tempTar -C $TmpDir
$tarOk = ($LASTEXITCODE -eq 0)
Remove-Item -Force $tempTar -ErrorAction SilentlyContinue
if (-not $tarOk) { Write-Host "[!] 解压失败" -ForegroundColor Red; exit 1 }

New-Item -ItemType Directory -Path (Join-Path $CodexDir "skills") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "agents") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "hooks\scripts") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "mcp") -Force | Out-Null
New-Item -ItemType Directory -Path (Join-Path $CodexDir "reference") -Force | Out-Null
Copy-Item (Join-Path $TmpDir "AGENTS.md") (Join-Path $CodexDir "AGENTS.md") -Force
Copy-Item (Join-Path $TmpDir "hooks.json") (Join-Path $CodexDir "hooks.json") -Force
if (Test-Path (Join-Path $TmpDir "config.toml")) { Copy-Item (Join-Path $TmpDir "config.toml") (Join-Path $CodexDir "config.toml") -Force }
Copy-Item -Recurse (Join-Path $TmpDir "skills\*") (Join-Path $CodexDir "skills") -Force
Copy-Item (Join-Path $TmpDir "agents\*.toml") (Join-Path $CodexDir "agents") -Force
Copy-Item (Join-Path $TmpDir "hooks\scripts\*.js") (Join-Path $CodexDir "hooks\scripts") -Force
Copy-Item -Recurse (Join-Path $TmpDir "mcp\*") (Join-Path $CodexDir "mcp") -Force
Copy-Item -Recurse (Join-Path $TmpDir "reference\*") (Join-Path $CodexDir "reference") -Force
# config.toml 中 __HY_CODEX_DIR__ 占位符替换为实际安装目录（MCP server 路径，正斜杠兼容 node）
$CodexCfg = Join-Path $CodexDir "config.toml"
if (Test-Path $CodexCfg) {
    $cfg = Get-Content $CodexCfg -Raw
    $cfg = $cfg.Replace("__HY_CODEX_DIR__", $CodexDir.Replace("\", "/"))
    [System.IO.File]::WriteAllText($CodexCfg, $cfg, (New-Object System.Text.UTF8Encoding($false)))
}
Remove-Item -Recurse -Force $TmpDir

Write-Host ""
Write-Host "[OK] hy 插件（Codex 版）安装完成！" -ForegroundColor Green
Write-Host ""
Write-Host "[!] 必须：在 codex 会话中运行 /hooks，逐个批准 2 个门禁 hook 信任" -ForegroundColor Yellow
Write-Host "    不批准 = 门禁不执行 = AI 可能直接 push"
Write-Host ""
Write-Host "[i] 使用方式（Codex 无斜杠命令，用自然语言触发）：" -ForegroundColor Cyan
Write-Host "    「运行 hy 自动路由：<需求>」 / 「运行 hy 增删改查流水线：<需求>」 等"
Write-Host "    完整命令映射与专家清单见 ~/.codex/AGENTS.md"
Write-Host "[i] 如果 codex 已打开，重启会话生效。" -ForegroundColor Cyan
